// Sends a test alert through the whole alert path (table, dashboard and, if you want, email).
// Set ALSO_SEND_EMAIL to true to receive a test email as well.
const ALSO_SEND_EMAIL = false;
return [{ json: { alert: {
  severity: 'test',
  type: 'test',
  title: 'Test alert from n8n',
  message: 'This is a drill sent from the “Email Intake → Alerts” workflow. Nothing is broken.',
  node: 'Send a test alert',
  workflow_name: 'Email Intake → Alerts',
  dedupe_key: `test|${Date.now()}`,
  email_test: ALSO_SEND_EMAIL,
} } }];

// Turns any problem into one alert: a failed workflow (Error Trigger), a failed step reported by the
// intake workflow (ClickUp or AI), a health-check finding, or a test. Decides if it should be emailed.
const store = $getWorkflowStaticData('global');
store.lastEmail = store.lastEmail || {};
store.recent = store.recent || {};
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

function hintFor(a) {
  const m = `${a.message || ''} ${a.details || ''}`.toLowerCase();
  const n = String(a.node || '').toLowerCase();
  if (/\b(401|403)\b|unauthori[sz]ed|forbidden|invalid_grant|token (has )?expired|invalid credentials|oauth/.test(m)) {
    if (n.includes('clickup')) return 'The ClickUp login is not valid any more: n8n → Credentials → ClickUp account → Reconnect, then publish the intake workflow again.';
    if (n.includes('gmail') || a.type === 'trigger_error' || a.type === 'gmail_unreachable') return 'The Gmail login is not valid any more: n8n → Credentials → Gmail account → Reconnect, then publish the intake workflow again.';
    return 'A login used by this node is not valid any more: reconnect its credential in n8n → Credentials.';
  }
  if (/\b429\b|rate.?limit|too many requests/.test(m)) return 'The service is rate-limiting n8n. It usually clears on its own; if it repeats, lower cfg_batch_limit in Settings.';
  if (/insufficient|quota|credits?\b|billing|exceeded your/.test(m)) return 'The AI provider is out of credits: add credits, or switch the OpenAI model node to your own credential.';
  if (/timed? ?out|etimedout|econnreset|socket hang up|\b50[234]\b|aborted/.test(m)) return 'A service did not answer in time. The next run tries again; if it repeats, check the service status and lower cfg_batch_limit.';
  if (/not found|\b404\b|does not exist/.test(m)) return 'Something this node points to no longer exists (a ClickUp list or task, or a data table). Check the IDs in the Settings node.';
  if (a.type === 'backlog') return 'Emails are waiting without being processed: open the intake workflow, check it is published, and look at its latest executions and the Gmail credential.';
  if (a.type === 'gmail_unreachable') return 'n8n could not read the inbox: n8n → Credentials → Gmail account → Reconnect.';
  if (a.type === 'ai_failed') return 'Nothing to do for one failure: the email is in Needs Review. If it repeats, check the AI credits or the model in n8n.';
  if (a.type === 'clickup_action_failed') return 'Open the execution to see what ClickUp answered, fix the cause, then create the task by hand from the email details.';
  if (a.type === 'test') return 'This is a drill. Acknowledge it on the dashboard to stop the sound.';
  return 'Open the execution in n8n: the failing node shows its input and the exact error.';
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const cfg = {
    url: String(j.cfg_monitor_url || '').trim(),
    email: String(j.cfg_alert_email || '').trim(),
    every: Number(j.cfg_email_every_min) || 15,
    base: String(j.cfg_n8n_url || '').replace(/\/$/, ''),
  };
  let a = null;
  if (j.execution || j.trigger) {
    // From the Error Trigger: a workflow stopped, or its trigger (Gmail) failed
    const ex = j.execution || {};
    const tr = j.trigger || {};
    const err = ex.error || tr.error || {};
    const wf = j.workflow || {};
    const node = ex.lastNodeExecuted || (err.node && err.node.name) || '';
    a = {
      severity: 'critical',
      type: j.trigger ? 'trigger_error' : 'workflow_error',
      title: j.trigger ? `The trigger of “${wf.name || 'a workflow'}” failed` : `“${wf.name || 'A workflow'}” stopped with an error`,
      message: String(err.message || 'Unknown error'),
      details: String(err.description || err.stack || '').slice(0, 1500),
      workflow_name: wf.name || '',
      workflow_id: String(wf.id || ''),
      node: node || (j.trigger ? 'Trigger' : ''),
      execution_id: String(ex.id || ''),
      execution_url: ex.url || (ex.id && cfg.base && wf.id ? `${cfg.base}/workflow/${wf.id}/executions/${ex.id}` : ''),
      mode: String(ex.mode || tr.mode || ''),
    };
  } else if (j.lane !== undefined && j.message_id !== undefined) {
    // From the intake workflow: one email whose ClickUp action or AI step failed
    const clickupFailed = j.action_ok === false;
    a = {
      severity: clickupFailed ? 'critical' : 'warning',
      type: clickupFailed ? 'clickup_action_failed' : 'ai_failed',
      title: clickupFailed ? (j.lane === 'FOLLOW_UP_COMMENT' ? 'ClickUp comment was not added' : 'ClickUp task was not created') : 'AI step failed for an email',
      message: String(j.error_message || j.reason || '') + (clickupFailed ? '' : ' The email went to Needs Review, so it is not lost.'),
      workflow_name: 'Email Intake → ClickUp (Part 1)',
      workflow_id: '6OEi2eVmBIKSBcmb',
      node: j.error_node || (clickupFailed ? 'ClickUp' : 'AI triage'),
      execution_id: String(j.execution_id || ''),
      message_id: String(j.message_id || ''),
      subject: String(j.subject || ''),
      mode: String(j.mode || ''),
    };
    a.execution_url = a.execution_id && cfg.base ? `${cfg.base}/workflow/${a.workflow_id}/executions/${a.execution_id}` : '';
  } else if (j.alert && typeof j.alert === 'object') {
    a = { ...j.alert };
  }
  if (!a) continue;

  const now = DateTime.now().setZone('Asia/Amman');
  a.alert_id = a.alert_id || `A-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
  a.created_at = now.toISO();
  a.dedupe_key = a.dedupe_key || `${a.type}|${a.node || ''}`;
  a.hint = a.hint || hintFor(a);
  a.details = a.details || '';

  // The same warning 3 times within an hour becomes critical (e.g. the AI keeps failing)
  const since = Date.now() - 3600000;
  store.recent[a.dedupe_key] = (store.recent[a.dedupe_key] || []).filter((t) => t > since).concat([Date.now()]);
  const times = store.recent[a.dedupe_key].length;
  if (a.severity === 'warning' && times >= 3) {
    a.severity = 'critical';
    a.title = `${a.title} (${times} times in the last hour)`;
  }

  // Email: critical alerts only, at most one per problem every cfg_email_every_min minutes
  const isTest = a.type === 'test';
  const wants = !!cfg.email && ((a.severity === 'critical' && !isTest) || a.email_test === true);
  const last = store.lastEmail[a.dedupe_key] || 0;
  a.should_email = wants && (a.email_test === true || Date.now() - last > cfg.every * 60000);
  if (a.should_email) store.lastEmail[a.dedupe_key] = Date.now();
  a.emailed = a.should_email;
  a.email_to = cfg.email;

  const dashboard = cfg.url.replace(/\/api\/ingest\/?$/, '/#alerts');
  const label = isTest ? 'TEST' : a.severity.toUpperCase();
  a.email_subject = `[${label}] Email intake: ${a.title}`;
  a.email_html = [
    `<div style="font-family:Arial,sans-serif;font-size:14px;color:#0e1330;max-width:620px">`,
    `<div style="background:${a.severity === 'critical' ? '#d03b3b' : '#4a3aa7'};color:#fff;padding:14px 18px;border-radius:10px 10px 0 0"><b>${esc(label)}</b> · ${esc(a.title)}</div>`,
    `<div style="border:1px solid #e3e5f0;border-top:0;padding:16px 18px;border-radius:0 0 10px 10px">`,
    `<p><b>What happened:</b> ${esc(a.message)}</p>`,
    `<p><b>Where:</b> ${esc(a.node || '—')}${a.workflow_name ? ` in ${esc(a.workflow_name)}` : ''}</p>`,
    a.subject ? `<p><b>Email:</b> ${esc(a.subject)}</p>` : '',
    `<p><b>When:</b> ${esc(now.toFormat('ccc d LLL yyyy, HH:mm'))} (Amman)</p>`,
    `<p style="background:#eef0ff;padding:10px 12px;border-radius:8px"><b>What to do:</b> ${esc(a.hint)}</p>`,
    `<p>${a.execution_url ? `<a href="${esc(a.execution_url)}">Open the execution in n8n</a>` : ''}${a.execution_url && dashboard.startsWith('http') ? ' · ' : ''}${dashboard.startsWith('http') ? `<a href="${esc(dashboard)}">Open the dashboard</a>` : ''}</p>`,
    `<p style="color:#767b9a;font-size:12px">Sent by the Email Intake alerts workflow. Repeats of the same problem are held back for ${cfg.every} minutes.</p>`,
    `</div></div>`,
  ].join('');
  a.monitor_url = cfg.url;
  delete a.email_test;
  out.push({ json: a });
}
return out;
